function biggestNumber(numbers) {
 let max = numbers[0];
 for (let i = 1; i < numbers.length; i++) {
 if (numbers[i] > max) {
 max = numbers[i];
 }
 }
 return max;
}

def count_vowels(text):
 vowels = ['a', 'e', 'i', 'o', 'u']
 return sum(1 for char in text if char.lower() in vowels)

def merge_dicts(a, b):
 """Merge two dictionaries by updating the first dictionary with keys from the second."""
 # Create a set of keys that are in both dictionaries
 common_keys = set(a.keys()) & set(b.keys())

 # Merge the dictionaries using the common keys
 merged_dict = {}
 for key in common_keys:
 merged_dict[key] = {**a.get(key, {}), **b.get(key, {})}

 return merged_dict

def second_largest(numbers):
 if len(numbers) < 2:
 return None

 numbers.sort()
 return numbers[-2]

def word_frequency(text):
 # Split the text into words and convert to lowercase
 words = [word.lower() for word in text.split()]

 # Create an empty dictionary to store word frequencies
 freq_dict = {}

 # Iterate over each word in the list
 for word in words:
 if word in freq_dict:
 freq_dict[word] += 1
 else:
 freq_dict[word] = 1

 return freq_dict
